package com.acme.university.enrolment;

import java.util.List;

/**
 * Blocks enrolment when the student has not passed every prerequisite of the course.
 */
public class PrerequisiteEnforcement {

    private final CourseRepository courses;
    private final TranscriptRepository transcripts;

    public PrerequisiteEnforcement(CourseRepository courses, TranscriptRepository transcripts) {
        this.courses = courses;
        this.transcripts = transcripts;
    }

    public void assertEligible(String studentId, String courseCode) {
        Course course = courses.require(courseCode);
        List<String> required = course.getPrerequisiteCodes();
        for (String pre : required) {
            if (!transcripts.hasPassed(studentId, pre)) {
                throw new PrerequisiteNotMetException(studentId, courseCode, pre);
            }
        }
    }
}

class PrerequisiteNotMetException extends RuntimeException {
    public PrerequisiteNotMetException(String studentId, String courseCode, String missing) {
        super("Student " + studentId + " has not passed " + missing + " required for " + courseCode);
    }
}

