package com.acme.university.grading;

import java.util.List;
import java.util.Map;

/**
 * Weighted final grade calculation followed by letter-grade conversion.
 */
public class FinalGradeCalculator {

    private final GradeScale scale;

    public FinalGradeCalculator(GradeScale scale) {
        this.scale = scale;
    }

    public String compute(List<ComponentMark> marks, Map<String, Double> weights) {
        double total = 0.0;
        double weightSum = 0.0;
        for (ComponentMark m : marks) {
            Double w = weights.get(m.getComponentCode());
            if (w == null) continue;
            total += m.getPercent() * w;
            weightSum += w;
        }
        if (weightSum <= 0.0) {
            throw new IllegalStateException("No weighted components recorded");
        }
        double normalised = total / weightSum;
        return scale.letterFor(normalised);
    }
}

