package com.acme.university.enrolment;

/**
 * Handles a student's enrolment request: capacity, prerequisites, persistence.
 */
public class EnrolmentService {

    private final CourseRepository courses;
    private final EnrolmentRepository enrolments;
    private final PrerequisiteEnforcement prerequisites;

    public EnrolmentService(CourseRepository courses,
                            EnrolmentRepository enrolments,
                            PrerequisiteEnforcement prerequisites) {
        this.courses = courses;
        this.enrolments = enrolments;
        this.prerequisites = prerequisites;
    }

    public Enrolment record(String studentId, String courseCode, String term) {
        Course c = courses.require(courseCode);
        prerequisites.assertEligible(studentId, courseCode);
        if (enrolments.countActive(courseCode, term) >= c.getCapacity()) {
            throw new CourseFullException(courseCode);
        }
        return enrolments.save(new Enrolment(studentId, courseCode, term));
    }
}

