package com.acme.university.grading;

/**
 * Records a single assignment mark, validating range against the assignment's max.
 */
public class AssignmentMarkRecorder {

    private final AssessmentRepository assessments;
    private final MarkRepository marks;

    public AssignmentMarkRecorder(AssessmentRepository assessments, MarkRepository marks) {
        this.assessments = assessments;
        this.marks = marks;
    }

    public ComponentMark record(String assessmentId, String studentId, double value) {
        Assessment a = assessments.require(assessmentId);
        if (value < 0 || value > a.getMaxMark()) {
            throw new IllegalArgumentException(
                "Mark " + value + " out of range 0.." + a.getMaxMark());
        }
        double percent = 100.0 * value / a.getMaxMark();
        ComponentMark cm = new ComponentMark(studentId, a.getComponentCode(), percent);
        return marks.save(cm);
    }
}

