package com.acme.university.results;

import java.time.Instant;

/**
 * Board-confirms results for a course: releases them and locks the marks.
 */
public class ResultsConfirmationService {

    private final ResultBoardRepository board;
    private final MarkRepository marks;
    private final TranscriptRepository transcripts;

    public ResultsConfirmationService(ResultBoardRepository board,
                                      MarkRepository marks,
                                      TranscriptRepository transcripts) {
        this.board = board;
        this.marks = marks;
        this.transcripts = transcripts;
    }

    public void confirm(String courseCode, String term) {
        if (board.isConfirmed(courseCode, term)) {
            throw new IllegalStateException("Already confirmed: " + courseCode + "/" + term);
        }
        transcripts.publish(courseCode, term, Instant.now());
        marks.lockAll(courseCode, term);
        board.markConfirmed(courseCode, term, Instant.now());
    }
}

