package com.acme.university.enrolment;

import java.util.List;

/**
 * Enforces the term course-load limit and prevents timetable clashes.
 */
public class EnrolmentLimitsPolicy {

    private static final int MAX_COURSES = 5;

    private final EnrolmentRepository enrolments;
    private final TimetableRepository timetables;

    public EnrolmentLimitsPolicy(EnrolmentRepository enrolments, TimetableRepository timetables) {
        this.enrolments = enrolments;
        this.timetables = timetables;
    }

    public void assertAllowed(String studentId, String courseCode, String term) {
        if (enrolments.countActive(studentId, term) >= MAX_COURSES) {
            throw new IllegalStateException("Already at max course load for " + term);
        }
        List<Session> newSessions = timetables.sessionsFor(courseCode, term);
        List<Session> existing = timetables.sessionsForStudent(studentId, term);
        for (Session s : newSessions) {
            for (Session e : existing) {
                if (s.clashesWith(e)) {
                    throw new TimetableClashException(courseCode, e.getCourseCode());
                }
            }
        }
    }
}

