import java.time.Instant;
import javax.persistence.EntityManager;
import javax.persistence.EntityTransaction;

/**
 * Persists an audit row whenever a mark is edited after initial entry.
 */
public class MarkChangeAuditor {

    private final EntityManager em;

    public MarkChangeAuditor(EntityManager em) {
        this.em = em;
    }

    public void recordEdit(String markId, double oldValue, double newValue, String editorId) {
        EntityTransaction tx = em.getTransaction();
        tx.begin();
        try {
            MarkAuditEntry entry = new MarkAuditEntry();
            entry.setMarkId(markId);
            entry.setOldValue(oldValue);
            entry.setNewValue(newValue);
            entry.setEditorId(editorId);
            entry.setOccurredAt(Instant.now());
            em.persist(entry);
            tx.commit();
        } catch (RuntimeException e) {
            tx.rollback();
            throw e;
        }
    }
}

