package com.acme.university.security;

import org.springframework.security.access.AccessDeniedException;

/**
 * Authorises mark changes: examiner or head, only before results confirmation.
 */
public class MarkEditPolicy {

    private final CourseRepository courses;
    private final ResultBoardRepository board;
    private final StaffDirectory staff;

    public MarkEditPolicy(CourseRepository courses,
                          ResultBoardRepository board,
                          StaffDirectory staff) {
        this.courses = courses;
        this.board = board;
        this.staff = staff;
    }

    public void assertMayEdit(String userId, String courseCode, String term) {
        if (board.isConfirmed(courseCode, term)) {
            throw new AccessDeniedException("Results already confirmed for " + courseCode);
        }
        Course c = courses.require(courseCode);
        boolean examiner = userId.equals(c.getExaminerId());
        boolean head = userId.equals(c.getDepartmentHeadId());
        if (!examiner && !head) {
            throw new AccessDeniedException("Only examiner or department head may edit marks");
        }
    }
}

