/* grade_export.c - export final grades as CSV, excluding withdrawn students */
#include <stdio.h>
#include "grades_db.h"

int export_grades(const char *term, const char *path) {
    FILE *out = fopen(path, "w");
    if (!out) return -1;
    fprintf(out, "student_id,course_code,percent,letter\n");

    db_cursor_t *cur = NULL;
    if (db_open_grade_cursor(&cur, term) != DB_OK) { fclose(out); return -2; }

    grade_row_t row;
    int rows = 0;
    while (db_grade_cursor_next(cur, &row) == DB_OK) {
        if (row.status == ENROLMENT_WITHDRAWN) continue;
        fprintf(out, "%s,%s,%.2f,%s\n",
                row.student_id, row.course_code, row.percent, row.letter);
        rows++;
    }
    db_close_cursor(cur);
    fclose(out);
    return rows;
}

